#pragma once

#include <AUI/Common/AOptional.h>
#include <AUI/Common/AString.h>
#include <AUI/IO/APath.h>

#include "Discovery.h"

namespace aui_remote {

/**
 * @brief Keys that authorize this client in the applications it has paired with.
 * @details
 * A key is generated by the client and stored in `~/.aui/remote/clients`, readable by the owner only. There are two
 * kinds:
 *
 * - the paired key, `<exe name>-<hash of exe path>.key`: the application remembers it, so it works after the
 *   application restarts (pairing is a one-time procedure);
 * - the session key, `<pid>-<startedAt>.session`: works until the application process exits (the application was
 *   launched by this client, or it does not remember paired clients). It is named after both the pid and the start
 *   time: a recycled pid does not pick up an old key.
 *
 * load() prefers the session key.
 */
class KeyStore {
public:
    explicit KeyStore(APath directory = defaultDirectory());

    /**
     * @return `~/.aui/remote/clients`
     */
    static APath defaultDirectory();

    /**
     * @return a random key of 32 hex characters
     */
    static AString generateKey();

    [[nodiscard]] const APath& directory() const noexcept { return mDirectory; }

    /**
     * @return where the paired key of the application is
     */
    [[nodiscard]] APath pathFor(const AppInfo& app) const;

    /**
     * @return where the session key of the application process is
     */
    [[nodiscard]] APath sessionPathFor(const AppInfo& app) const;

    /**
     * @return the key to connect to the application with; nothing if the client is not paired
     */
    [[nodiscard]] AOptional<AString> load(const AppInfo& app) const;

    /**
     * @brief Stores the paired key.
     */
    void store(const AppInfo& app, const AString& key) const;

    /**
     * @brief Stores the key that is valid until the application process exits.
     */
    void storeSession(const AppInfo& app, const AString& key) const;

    /**
     * @brief Forgets both keys of the application.
     */
    void remove(const AppInfo& app) const;

    /**
     * @brief Deletes session keys of processes that are not in `alive`.
     */
    void pruneExcept(const AVector<AppInfo>& alive) const;

private:
    APath mDirectory;
};

}   // namespace aui_remote
